import{_ as r,o as l,c as o,ag as e}from"./chunks/framework.DzGOF12C.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"불교의 기본 개념","slug":"불교의-기본-개념","link":"#불교의-기본-개념","children":[]},{"level":2,"title":"아리안족의 인도 유입과 브라마니즘","slug":"아리안족의-인도-유입과-브라마니즘","link":"#아리안족의-인도-유입과-브라마니즘","children":[]},{"level":2,"title":"불교의 발생","slug":"불교의-발생","link":"#불교의-발생","children":[]},{"level":2,"title":"최초의 가르침 (중도설)과 깨달은 내용 (연기설)","slug":"최초의-가르침-중도설-과-깨달은-내용-연기설","link":"#최초의-가르침-중도설-과-깨달은-내용-연기설","children":[]},{"level":2,"title":"인간관(오온)과 세계관(18계)","slug":"인간관-오온-과-세계관-18계","link":"#인간관-오온-과-세계관-18계","children":[]},{"level":2,"title":"사성제","slug":"사성제","link":"#사성제","children":[]}],"relativePath":"philosophy/Korean-Philosophy/03. 불교적 배경.md","filePath":"philosophy/Korean-Philosophy/03. 불교적 배경.md"}'),a={name:"philosophy/Korean-Philosophy/03. 불교적 배경.md"};function n(i,t,s,d,h,p){return l(),o("div",null,[...t[0]||(t[0]=[e('<blockquote><p>원효 등 한국 불교사상을 다루기 전, 인도에서 불교가 발생한 배경과 기본 개념을 정리.</p></blockquote><h2 id="불교의-기본-개념" tabindex="-1">불교의 기본 개념 <a class="header-anchor" href="#불교의-기본-개념" aria-label="Permalink to &quot;불교의 기본 개념&quot;">​</a></h2><p><strong>고통의 원인</strong>: 내가 원하는 것을 얻지 못하기 때문에 고통스러워함. 세상에 고정된 것은 없음 — 제행무상, 제법무아.</p><p><strong>공(空)</strong>: 일수사견(같은 물이라도 보는 존재에 따라 다르게 보임)처럼, 불교는 인간 사유의 기존 형식논리 규칙을 그대로 따르지 않음. 공이란 유(有)도 아니고 무(無)도 아니며, 유이면서 무인 것도 아니고 무이면서 유인 것도 아님 — 형식논리의 동일률·모순율·배중률로는 설명할 수 없음.</p><h2 id="아리안족의-인도-유입과-브라마니즘" tabindex="-1">아리안족의 인도 유입과 브라마니즘 <a class="header-anchor" href="#아리안족의-인도-유입과-브라마니즘" aria-label="Permalink to &quot;아리안족의 인도 유입과 브라마니즘&quot;">​</a></h2><p>아리안 문화와 인더스 문화가 결합해 브라마니즘이 탄생. 우주를 관통하는 근원적이고 절대적인 실체(<strong>브라흐만</strong>)를 상정함 — 브라흐만은 언어로 표현할 수도, 보거나 듣거나 생각할 수도 없는 모든 존재의 기반. <strong>아트만</strong>의 형태로 인간에게 브라흐만이 내재해 있으며, 브라흐만의 존재를 인식하고 그것이 곧 나임을 깨닫는 것(범아일여)이 중요함.</p><p>브라마니즘 사회의 특징: 계급사회, 내세의 해탈 추구, 고행 추구(출가 문화).</p><h2 id="불교의-발생" tabindex="-1">불교의 발생 <a class="header-anchor" href="#불교의-발생" aria-label="Permalink to &quot;불교의 발생&quot;">​</a></h2><p>철기문화가 유입되며 생산성이 증대해 잉여생산물이 발생하고, 이를 중심으로 시장·도시가 형성되며 자유사상가들이 등장. 이 흐름 속에서 불교는 브라마니즘과 대비되는 방향으로 나타남:</p><table tabindex="0"><thead><tr><th>브라마니즘</th><th>불교</th></tr></thead><tbody><tr><td>신 중심</td><td>인간 중심</td></tr><tr><td>계급사회</td><td>평등사회</td></tr><tr><td>내세의 해탈</td><td>현세 해탈</td></tr><tr><td>고행주의</td><td>중도</td></tr></tbody></table><h2 id="최초의-가르침-중도설-과-깨달은-내용-연기설" tabindex="-1">최초의 가르침 (중도설)과 깨달은 내용 (연기설) <a class="header-anchor" href="#최초의-가르침-중도설-과-깨달은-내용-연기설" aria-label="Permalink to &quot;최초의 가르침 (중도설)과 깨달은 내용 (연기설)&quot;">​</a></h2><p>인간의 생각은 (세상에) 고정된 실체가 있다고 전제하지만, 현실은 모든 것이 변함 — 변하지 않는 실체를 찾으려는 인간과, 그런 실체가 없는 현실 사이의 괴리에서 고통이 발생함.</p><p>&#39;나&#39;라는 존재는 원래 &#39;무아&#39;임을 깨닫고, 해탈을 통해 고통에서 벗어나야 함. <strong>무명</strong>(세상이 연기(緣起)라는 것을 모르는 상태)에서 여러 인과관계를 거쳐 &quot;고정된 실체가 있다&quot;고 믿는 상태로, 삶을 반복해서 살게 됨.</p><h2 id="인간관-오온-과-세계관-18계" tabindex="-1">인간관(오온)과 세계관(18계) <a class="header-anchor" href="#인간관-오온-과-세계관-18계" aria-label="Permalink to &quot;인간관(오온)과 세계관(18계)&quot;">​</a></h2><p><strong>오온</strong>: 인간을 구성하는 5가지 요소의 조합 — 색·수·상·행·식</p><ul><li><strong>색</strong>: 물질적 요소 (다시 안·이·비·설·신으로 구분)</li><li><strong>수</strong>: 외부 대상에 대한 정보를 받아들이는 것</li><li><strong>상</strong>: 감각자료를 (아직 이해할 수 없는) 관념으로 변환하는 것</li><li><strong>행</strong>: 그 관념을 읽으려는 의지</li><li><strong>식</strong>: 관념을 읽어내는 인식작용</li></ul><p>&#39;나&#39;라는 개별적 존재는 고정되어 정해져 있는 것이 아니라, 그때그때 오온의 조합으로 존재함.</p><p><strong>18계</strong>: 오온을 다시 6근·6경·6식으로 구분할 수 있음 — 6근(안이비설신의라는 인식기관)으로부터 그 대상인 6경이, 다시 그로부터 의식인 6식이 나타남. 이러한 감관 요소·대상·의식 18개가 세계를 구성함.</p><h2 id="사성제" tabindex="-1">사성제 <a class="header-anchor" href="#사성제" aria-label="Permalink to &quot;사성제&quot;">​</a></h2><p>네 가지 성스러운 진리</p><ul><li><strong>고성제</strong>: 모든 인간은 고통 속에 산다</li><li><strong>집성제</strong>: 고정된 실체가 있다고 믿기 때문에 집착이 생긴다 (탐·진·치 삼독)</li><li><strong>멸성제</strong>: 괴로움의 소멸에 대한 진리</li><li><strong>도성제</strong>: 그 집착을 소멸시키는 방법에 대한 진리 — 중도의 수양을 통해 연기를 깨우쳐야 함, 그 구체적 방법이 <strong>팔정도</strong></li></ul>',21)])])}const u=r(a,[["render",n]]);export{c as __pageData,u as default};
